```ts
import { describe, it, expect, beforeEach } from 'vitest';
import { WatchlistStore } from '../app/watchlist-store';

const tmdb = (id: number) => ({
  id,
  title: `Movie ${id}`,
  release_date: '2020-01-01',
  poster_path: null,
  overview: 'A test movie',
});

describe('WatchlistStore.clearWatched', () => {
  beforeEach(() => {
    localStorage.clear();
  });

  it('removes every watched movie and keeps unwatched ones in order', () => {
    const store = new WatchlistStore();
    store.add(tmdb(1));
    store.add(tmdb(2));
    store.add(tmdb(3));
    store.add(tmdb(4));
    store.toggleWatched(2);
    store.toggleWatched(4);

    store.clearWatched();

    expect(store.items().map((m) => m.id)).toEqual([1, 3]);
    expect(store.count()).toBe(2);
    expect(store.watchedCount()).toBe(0);
  });

  it('leaves the list untouched when no movie is watched', () => {
    const store = new WatchlistStore();
    store.add(tmdb(1));
    store.add(tmdb(2));

    store.clearWatched();

    expect(store.items().map((m) => m.id)).toEqual([1, 2]);
    expect(store.count()).toBe(2);
    expect(store.watchedCount()).toBe(0);
  });

  it('persists the cleared list so a newly constructed store sees it', () => {
    const store = new WatchlistStore();
    store.add(tmdb(1));
    store.add(tmdb(2));
    store.add(tmdb(3));
    store.toggleWatched(1);
    store.toggleWatched(3);

    store.clearWatched();

    const fresh = new WatchlistStore();
    expect(fresh.items().map((m) => m.id)).toEqual([2]);
    expect(fresh.count()).toBe(1);
    expect(fresh.watchedCount()).toBe(0);
  });
});
```

