```ts
import { ApplicationRef } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { TmdbMovie } from './movie';
import { WatchlistStore } from './watchlist-store';

function tmdbMovie(id: number, title: string): TmdbMovie {
  return {
    id,
    title,
    release_date: `${2000 + id}-01-01`,
    poster_path: id % 2 === 0 ? null : `/poster-${id}.jpg`,
    overview: `Overview of ${title}`
  };
}

/**
 * The store persists its items from an `effect()`, which Angular runs
 * asynchronously. Flush the scheduler so localStorage reflects the
 * latest state, the way it would in a running application.
 */
function flushReactiveEffects(): void {
  const testBed = TestBed as unknown as {
    tick?: () => void;
    flushEffects?: () => void;
  };
  if (typeof testBed.tick === 'function') {
    testBed.tick();
  } else if (typeof testBed.flushEffects === 'function') {
    testBed.flushEffects();
  } else {
    TestBed.inject(ApplicationRef).tick();
  }
}

